ee:message.ee:set-payload:
%dw 2.0
output application/json
---
(vars.evaluateCreatePayload default []) ++ (vars.evaluateUpdatePayload default [])
//{
//	"create": vars.evaluateCreatePayload,
//	"update": vars.evaluateCreatePayload
//}

%dw 2.0
import * from dw::core::Arrays
import lines from dw::core::Strings
import remove from dw::core::Strings
output application/json
var report = vars.initialReportPayload
---
{
	"reportPayload": {
		"eventId": vars.transactionId,
		"Timestamp": now(),
		"TotalSuccessCreated": (report.Create.TotalSuccessRecord as Number) default 0,
		"TotalSuccessUpdated": (report.Update.TotalSuccessRecord as Number) default 0,
		"TotalFailedCreated" : (report.Create.TotalFailedRecord as Number) default 0,
		"TotalFailedUpdated" : (report.Update.TotalFailedRecord as Number) default 0,
		"FailedData": {
			"created": report.Create.ErrorsDuringBatchProcess default [],
			"updated": report.Update.ErrorsDuringBatchProcess default []
		}

	},
	"reportAttachment":{

		"eventId": vars.transactionId,
		"Timestamp": now(),
		"NumericReport": {
			"StartTimestamp": vars.startTimeStamp,
			"EndTimestamp": now(),
			"ProcessDuration": ((((now() - (vars.startTimeStamp as DateTime) ) as Number)/60) as String {format: "#0.00"}) ++ " " ++  "Minutes",
			"TotalProductChanges": report.Update.TotalProductChanges default 0,
			"TotalProductChangesWithout555": report.Update.TotalProductChangesWithout555 default 0,
			"TotalPreFilterCount": ((report.Create.TotalPreFilterCount as Number) default 0) + ((report.Update.TotalPreFilterCount as Number) default 0),
			"TotalPostFilterCount": ((report.Create.TotalPostFilterCount as Number) default 0) + ((report.Update.TotalPostFilterCount as Number) default 0),
			"TotalProductSendToSalesforce": ((report.Create.TotalSuccessRecord as Number) default 0) + ((report.Update.TotalSuccessRecord as Number) default 0) + ((report.Create.TotalFailedRecord as Number) default 0) + (report.Update.TotalFailedRecord as Number) default 0,
			"Successful-Report": {
					"Create-Record-Report":{
							"TotalPostFilterCountToCreate": (report.Create.TotalPostFilterCount as Number) default 0,
						    "TotalProductCreatedToSalesforce": (report.Create.TotalSuccessRecord as Number) default 0,
						    "TotalProductFailedToCreateInSalesforce": (report.Create.TotalFailedRecord as Number) default 0,
						    "ErrorsDuringBatchProcessCreate": report.Create.ErrorsDuringBatchProcess
				    	},
				    "Update-Record-Report":{
				    		"TotalPostFilterCountToUpdate": (report.Update.TotalPostFilterCount as Number) default 0,
				    		"TotalProductSuccessfullyUpdatedToSalesforce": (report.Update.TotalSuccessRecord as Number) default 0,
				    		"TotalProductFailedToUpdateInSalesforce": (report.Update.TotalFailedRecord as Number) default 0,
						    "ErrorsDuringBatchProcessUpdate": report.Update.ErrorsDuringBatchProcess
				        }
			},
			"Failed-Report":{
				"Create-Failed-Record-Report":{
					"TotalFailedToCreateRecordsDuringPreFilterCount": sizeOf(payload.failedCreateRecord remove "\"" splitBy  ",") default 0,
					"TotalFailedToCreateRecordsBeforeSendingToSalesforceCount": sizeOf(payload.failedCreateRecordAfterFilter remove "\"" splitBy  ",") default 0,
				},
				"Update-Failed-Record-Report":{
					"TotalFailedToUpdateRecordsDuringPreFilterCount": sizeOf(payload.failedUpdateRecord remove "\"" splitBy  ",") default 0,
					"TotalFailedToUpdateRecordsBeforeSendingToSalesforceCount": sizeOf(payload.failedUpdateRecordAfterFilter remove "\"" splitBy  ",") default 0
				}
			}
		},
		"FailedDataReport":{

				"FailedToCreateRecordsDuringPreFilterList": (payload.failedCreateRecord remove "\"") default "No failed Records",
				"FailedToCreateRecordsBeforeSendingToSalesforceList": (payload.failedCreateRecordAfterFilter remove "\"") default "No failed Records",
				("ISBN13ToCreateInSalesforce": (payload.errorInsertToSalesforce remove "\"")) if(payload.errorInsertToSalesforce != null),
				"FailedToUpdateRecordsDuringPreFilterList": (payload.failedUpdateRecord remove "\"") default "No failed Records",
				"FailedToUpdateRecordsBeforeSendingToSalesforceList": (payload.failedUpdateRecordAfterFilter remove "\"") default "No failed Records"

		}
	}

}

ee:message.ee:set-attributes:
%dw 2.0
output application/json
---
"queryParams":{
	"createdFrom": if(attributes.queryParams.setDate != null)
							attributes.queryParams.setDate
						else
							((now() as LocalDateTime >> "Asia/Manila")-(Mule::p('extract.dynamicPeriod') as Period)) as String {format: "yyyy-MM-dd"}
}

%dw 2.0
output application/json
---
"queryParams":{
	"updatedFrom": if(attributes.queryParams.setDate != null)
							attributes.queryParams.setDate
						else
							((now() as LocalDateTime >> "Asia/Manila")-(Mule::p('extract.dynamicPeriod') as Period)) as String {format: "yyyy-MM-dd"}
}

%dw 2.0
output application/json
---
"queryParams":{
	"updatedFromProductSizes": if(attributes.queryParams.setDate != null)
							attributes.queryParams.setDate
						else
							((now() as LocalDateTime >> "Asia/Manila")-(Mule::p('extract.dynamicPeriod') as Period)) as String {format: "yyyy-MM-dd"}
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
(vars.isbnList default [] -- (vars.isbn13ListExist.*'ISBN_13__c' default [])) map (item,index) -> {
	"isbn13": item
}

ee:variables.ee:set-variable:
%dw 2.0 import first from dw::core::Strings import * from dw::core::Arrays output application/json var initialNum = 0 --- vars.aggregatedPayload filter ( ( ((Mule::p('include.imprintCode') splitBy "," contains ($.internal.productInternal.imprintCode first 1)) and (not (Mule::p('excluded.formats') splitBy "," contains ($.main.productMain.cambridgeFormat.code))) and ( (//English Filters ( ($.internal.productInternal.imprintCode first 1) == "3" or ($.internal.productInternal.imprintCode first 1) == "4" ) and ($.globalPub.ext.dataReleaseFlag == "Y") ) or (//Academic Filters ( ($.internal.productInternal.imprintCode first 1) == "1" or ($.internal.productInternal.imprintCode first 1) == "2" ) )
) and $.internal.productInternal.masterProfitCentreCode != "6002" ) or $.main.productMain.cambridgeFormat.code == "RE"
) and $.main.productMain.cambridgeFormat.code != null
)

%dw 2.0
output application/json
var successData = vars.secondFilterPayload default [] map(item, index) -> 
		{
			"isbn13": item.isbn13,
			"rule-evaluation": true,
			"pre-filter-payload": {
				"format": item.main.productMain.cambridgeFormat.code,
				"imprint_code": item.internal.productInternal.imprintCode,
				"dataReleaseFlag": item.globalPub.ext.dataReleaseFlag,
				"masterProfitCentreCode": item.internal.productInternal.masterProfitCentreCode,
				"regionalAvailability": item.regAvail.regionalAvailability map (regionalAvail, ctr) -> {
					"vistaRegionCode": regionalAvail.vistaRegionCode,
					"vistaAnswerCode": regionalAvail.vistaAnswerCode.code,
					"vistaAvailCode": regionalAvail.vistaAvailability.code,
					"vistaAvailDescriptionShort": regionalAvail.vistaAvailability.descriptionShort
				}

			}
		} default [] 
var failedData = ((vars.aggregatedPayload default []) -- (vars.secondFilterPayload default []))  map(item, index) -> 
		{
			"isbn13": item.isbn13,
			"rule-evaluation": false,
			"pre-filter-payload": {
				"format": item.main.productMain.cambridgeFormat.code,
				"imprint_code": item.internal.productInternal.imprintCode,
				"dataReleaseFlag": item.globalPub.ext.dataReleaseFlag,
				"masterProfitCentreCode": item.internal.productInternal.masterProfitCentreCode,
				"regionalAvailability": item.regAvail.regionalAvailability map (regionalAvail, ctr) -> {
					"vistaRegionCode": regionalAvail.vistaRegionCode,
					"vistaAnswerCode": regionalAvail.vistaAnswerCode.code,
					"vistaAvailCode": regionalAvail.vistaAvailability.code,
					"vistaAvailDescriptionShort": regionalAvail.vistaAvailability.descriptionShort
				}

			} 

		} default []

var combinedData = successData ++ failedData
var isPassed = if(vars.qParams.passed == "true")
					successData
				else if(vars.qParams.passed == "false")
					failedData
				else
					combinedData
---
vars.isbn13Container ++ isPassed

%dw 2.0
//@StreamCapable()
//input payload application/json
output application/json //deferred=true

---
vars.successContainer << (vars.payload_item ++ 
	{("product":vars.productV2[0]) if(vars.productV2[0] != null)} ++
	{("contributions":vars.contributions[0].contributions) if(vars.contributions[0] != null)} ++
	{("marketRestrictions":vars.marketRestrictions[0].marketRestrictionsText) if(vars.marketRestrictions[0].marketRestrictionsText != null)}++
	{("globalPublications":vars.globalPub[0]) if(vars.globalPub[0] != null)} ++
	{("salesStatus":vars.salesStatus[0].salesStatuses) if(vars.salesStatus[0].salesStatuses != null)} ++
	{("cambridgeCore": vars.cambridgeCore[0]) if(vars.cambridgeCore[0] != null)} ++
	{("dataReleaseActualDate": vars.datashop[0]) if(vars.datashop[0] != null)} ++
	{("gratisFlag": vars.ecommerceCategories[0].gratisPolicy) if(vars.ecommerceCategories[0].gratisPolicy != null)} 
	++
	{("techPlatform" : vars.techPlatform[0].technologyPlatforms) if(vars.techPlatform[0].technologyPlatforms != null)} 
	++ {("cartaEditor": vars.cartaEditor[0]) if(vars.cartaEditor[0] != null)}
	++ {("odhMarketingController": vars.odhMarketingController[0]) if(vars.odhMarketingController[0] != null)}
	)

