itCentreCode default null, "Publisher_Site__c": item.product.productInternal.vistaProfitCentre default null, "Asset_Url__c": if(item.product.assets != []) item.product.assets filter ($.assetType contains "Large Size Cover") map $.assetUrl joinBy "" withMaxSize 255 else null, "Blurb150__c": if(item.product.productBlurbs != []) item.product.productBlurbs filter ($.blurbType contains "Blurb 150") map $.blurbText joinBy "" withMaxSize 32768 else null, "issueBlurb__c": if(item.product.productBlurbs != []) item.product.productBlurbs filter ($.blurbType contains "Blurb Issue Level") map $.blurbText joinBy "" withMaxSize 32768 else null, "Inspection_Permitted__c": item.product.rights.inspectionCopiesAllowed match{ case "Y" -> true case "N" -> false else -> false }, "Esamples_Permitted__c": if(item.product.productMain.cambridgeFormat.code == "RE") true else false, "RecordTypeId": Mule::p('controlled.product'), "IsActive": true, //"Hierarchy_Level__c": item default "Issue", "Higher_Subject_Code__c": item.product.vistaSubjects.subject1Code default null, "Higher_Subject_Code_Description__c": item.product.vistaSubjects.subject1 default null, "Subject_Code__c": item.product.vistaSubjects.subject2Code default null, "Subject_Description__c": item.product.vistaSubjects.subject2 default null, "Extra_Subject_Code__c": item.product.vistaSubjects.subject3Code default null, "Extra_Subject_Description__c": item.product.vistaSubjects.subject3 default null, "Core_Product_Group_Code__c": item.cambridgeCore.COREPRODUCTGROUPCODE default null, "Core_Product_Group__c": item.cambridgeCore.COREPRODUCTGROUP default null, "Title_Code__c": item.cambridgeCore.TITLE_CODE as String default "", "Global_First_Pub_Date__c": if(item.product.productEvents != null) ((item.product.productEvents filter($.eventType == "global_first_pub_date") map $.eventTimestamp joinBy "") as LocalDateTime as Date {format: "yyyy-MM-dd"} default null) else null, // use product events "Publication_Date__c": if(item.product.productEvents != null) ((item.product.productEvents filter($.eventType == "global_pub_date") map $.eventTimestamp joinBy "") as LocalDateTime as Date {format: "yyyy-MM-dd"} default null) else null, //use product events "Data_Fixed__c": if(item.globalPublications.ext.dataReleaseFlag == "Y") true else false, "market_restrictions__c": item.marketRestrictions default null, "Data_Release_Actual_Date__c": if(item.dataReleaseActualDate != null) ((item.dataReleaseActualDate.DATA_RELEASE_ACTUAL_DATE as LocalDateTime as Date {format: "yyyy-MM-dd"}) default null) else null, "Author__c": (item.contributions map(contri, contriIndex)-> contri.forename ++ " " ++ contri.surname) joinBy "/" withMaxSize 254, "sales_status_uk__c": salesStatusFunc("1201", item.salesStatus), "sales_status_us__c": salesStatusFunc("1214", item.salesStatus), "sales_status_asia__c": salesStatusFunc("1288", item.salesStatus), "sales_status_iberia__c": salesStatusFunc("2101", item.salesStatus), "sales_status_australia__c": salesStatusFunc("2501", item.salesStatus), "sales_status_india__c": salesStatusFunc("5401", item.salesStatus), "sales_status_south_africa__c": salesStatusFunc("4601", item.salesStatus), "Availability_Code_UK__c": availabilityFunc("C", item.product.regionalAvailability) default null,//based on vistaRegion "Availability_Code_US__c": availabilityFunc("N", item.product.regionalAvailability) default null, "Availability_Code_ASIA__c": availabilityFunc("E", item.product.regionalAvailability) default null, "Availability_Code_Iberia__c": availabilityFunc("I", item.product.regionalAvailability) default null, "Availability_Code_Australia__c": availabilityFunc("A", item.product.regionalAvailability) default null, "Availability_Code_India__c": availabilityFunc("D", item.product.regionalAvailability) default null, "Availability_Code_South_Africa__c": availabilityFunc("R", item.product.regionalAvailability) default null, "Answer_Code_UK__c": answerFunc("C", item.product.regionalAvailability) default null,//based on vistaRegion "Answer_Code_US__c": answerFunc("N", item.product.regionalAvailability) default null, "Answer_Code_ASIA__c": answerFunc("E", item.product.regionalAvailability) default null, "Answer_Code_Iberia__c": answerFunc("I", item.product.regionalAvailability) default null, "Answer_Code_Australia__c": answerFunc("A", item.product.regionalAvailability) default null, "Answer_Code_India__c": answerFunc("D", item.product.regionalAvailability) default null, "Answer_Code_South_Africa__c": answerFunc("R", item.product.regionalAvailability) default null, "regional_availability_date_uk__c": regionalDateFunc("C", item.product.regionalAvailability) as LocalDateTime as Date {format: "yyyy-MM-dd"} default null, "regional_availability_date_us__c": regionalDateFunc("N", item.product.regionalAvailability) as LocalDateTime as Date {format: "yyyy-MM-dd"} default null, "regional_availability_date_asia__c": regionalDateFunc("E", item.product.regionalAvailability) as LocalDateTime as Date {format: "yyyy-MM-dd"} default null, "regional_availability_date_iberia__c": regionalDateFunc("I", item.product.regionalAvailability) as LocalDateTime as Date {format: "yyyy-MM-dd"} default null, "regional_availability_date_australia__c": regionalDateFunc("A", item.product.regionalAvailability) as LocalDateTime as Date {format: "yyyy-MM-dd"} default null, "regional_availability_date_india__c": regionalDateFunc("D", item.product.regionalAvailability) as LocalDateTime as Date {format: "yyyy-MM-dd"} default null, "regional_availability_date_south_africa__c": regionalDateFunc("R", item.product.regionalAvailability) as LocalDateTime as Date {format: "yyyy-MM-dd"} default null, "editor__c": if(!isEmpty(item.odhMarketingController.EDITOR_NAME)) item.odhMarketingController.EDITOR_NAME else item.cartaEditor.legend default null, "marketing_controller__c": item.odhMarketingController.UK_MARKETING_CONTROLLER default null, "Content_Category__c": item.product.educational.contentCategory default null, "Discount_Terms__c": item.product.globalDiscountTerm.legend default null, "Page_Extent__c": item.product.productSizes filter ($."type" == "pageExtent") map $.value joinBy "" default null, "Page_Size_Height_mm__c": item.product.productSizes filter ($."type" == "height_mm") map $.value joinBy "" default null, "Page_Size_Width_mm__c": item.product.productSizes filter ($."type" == "width_mm") map $.value joinBy "" default null
