%dw 2.0
output application/json
---
{
    "queryString": "SELECT ci.EAN_NUMBER, cbo.CBO_PRODUCT_GROUP AS coreProductGroupCode, pg.CCP_PRODUCT_GROUP_LEGEND  AS coreProductGroup, ci.TITLE_CODE FROM ORALIV.CORE_ISBN ci LEFT JOIN ORALIV.CORE_ISBN_CBO cbo ON ci.EAN_NUMBER = cbo.EAN_NUMBER LEFT JOIN APP_SYSREF.SR_CCP_PRODUCT_GROUP_ORA pg ON cbo.CBO_PRODUCT_GROUP = pg.CCP_PRODUCT_GROUP WHERE ci.EAN_NUMBER = :eanNumber",
    "bindValues": {
        "eanNumber": payload.isbn13 as String
    }
}

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	"from": Mule::p('report.tokenCheck.sender'),
	"to": Mule::p('report.tokenCheck.recipient') splitBy ",",
	"subject": upper(Mule::p('mule.env')) ++ " - " ++ Mule::p('report.emailSettings.subject'),
	"body": "$(write(payload.reportPayload, 'application/json'))",
	"attachments": [
		{
			"name": "Failed Records Report Attachment - "++ (now() as Number) as String,
			"content": write(payload.reportAttachment, 'application/json')
		} 
	],
	"contentType": "text/plain"
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    "queryString": "SELECT FIRST_DATE_SENT AS data_release_actual_date FROM oraliv.dshop_cup_isbn_sent_first WHERE ean_number = :eanNumber",
    "bindValues": {
        "eanNumber": payload.isbn13 as String
    }
}
